assert(sh(`git rev-parse ${PARENT}:${TARGET}`)===PARENT_BLOB,'parent blob drift');assert(sh(`git hash-object ${TARGET}`)===TARGET_BLOB,'target blob drift');const parent=cp.execFileSync('git',['show',`${PARENT}:${TARGET}`],{encoding:'utf8'}),p=parse(parent);assert(p.declarations.length===77&&p.dead.length===2,`parent parse drift ${p.declarations.length}/${p.dead.length}`);const [a,b]=p.dead,SEL='body.before-after-preview-open .before-after-preview__scrim';assert(a.line===15&&a.property==='-webkit-backdrop-filter'&&a.value==='blur(14px) saturate(0.96)'&&a.winnerLine===47&&a.winnerValue==='blur(24px) saturate(1.04)','webkit drift');assert(b.line===16&&b.property==='backdrop-filter'&&b.value==='blur(14px) saturate(0.96)'&&b.winnerLine===48&&b.winnerValue==='blur(24px) saturate(1.04)','standard drift');for(const d of [a,b])assert(d.selector===SEL&&d.winnerSelector===SEL&&d.context===''&&d.winnerContext===''&&!d.important&&!d.winnerImportant&&d.winnerLine>d.line,'dominance drift');const nl=/\r?\n$/.test(parent),ls=parent.split(/\r?\n/);if(nl&&ls.at(-1)==='')ls.pop();for(const d of [b,a])ls.splice(d.line-1,1);const rebuilt=Buffer.from(ls.join('\n')+(nl?'\n':'')),actual=fs.readFileSync(TARGET);assert(Buffer.compare(rebuilt,actual)===0,'independent reconstruction mismatch');const q=parse(actual.toString('utf8'));assert(q.declarations.length===75&&q.dead.length===0,`target parse drift ${q.declarations.length}/${q.dead.length}`);const hash=crypto.createHash('sha256').update(actual).digest('hex');assert(hash===HASH&&actual.length===BYTES,`identity drift ${hash}/${actual.length}`);console.log(`INDEPENDENT RECONSTRUCTION PASS|parentDecl=77|parentDead=2|targetDecl=75|targetDead=0|unconditionalDominance=2|hash=${hash}|bytes=${actual.length}|byteIdentical=1`);
